// Builds app/ds/tokens.css from app/ds/tokens.json (a copy of the Condisco Design System artifact's tokens.json,
// https://claude.ai/artifact/1Wq3HH1mTjxFr6yhLhtxEp ) and the kit's token block (kit/template.html between the
// DS:TOKENS markers). Colours use light-dark() so the app's [data-theme] switch keeps working.
// Usage: node scripts/build-tokens.mjs [--check]   (--check fails when a generated file is out of date)
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const SRC = path.join(ROOT, 'app/ds/tokens.json');
const OUT = path.join(ROOT, 'app/ds/tokens.css');
const KIT = path.join(ROOT, 'kit/template.html');
const t = JSON.parse(fs.readFileSync(SRC, 'utf8'));

const colour = (tok) => (typeof tok.value === 'string' ? tok.value
  : tok.value.dark && tok.value.dark !== tok.value.light ? `light-dark(${tok.value.light},${tok.value.dark})` : tok.value.light);
const list = (fam) => (t[fam]?.tokens || []).map((x) => `--${x.name}:${x.value}`);
// light-dark() only takes colours, so shadows switch through the theme blocks below instead.
const shadowLight = (t.shadow?.tokens || []).map((x) => `--${x.name}:${typeof x.value === 'string' ? x.value : x.value.light}`);
const shadowDark = (t.shadow?.tokens || []).filter((x) => typeof x.value !== 'string').map((x) => `--${x.name}:${x.value.dark}`);
const styles = t.type.groups.flatMap((g) => g.styles.map((s) => ({ ...s, family: s.family || g.family })));
const fs_ = styles.map((s) => `--fs-${s.name}:${s.fontSize};--lh-${s.name}:${s.lineHeight}`);
const fam = Object.entries(t.type.families).map(([k, v]) => `--font-${k}:${v}`);

const COLORS = t.color.tokens.map((x) => `--${x.name}:${colour(x)}`);
// Old names kept as aliases for one release (0.5.x) so nothing breaks while screens migrate. Remove in 0.6.
const LEGACY = [
  '--sunk:var(--surface-sunk)', '--muted:var(--ink-2)', '--hero:var(--surface-deep)', '--hero-ink:var(--ink-on-deep)',
  '--hero-line:light-dark(transparent,#2b3848)', '--line-soft:var(--line)', '--frost:var(--glass)',
  '--sh-1:light-dark(rgba(27,52,80,.05),rgba(0,0,0,.25))', '--sh-2:light-dark(rgba(27,52,80,.13),rgba(0,0,0,.45))',
  '--shadow:var(--shadow-1)', '--shadow-up:var(--shadow-2)', '--ease:var(--ease-out)',
  '--s1:var(--space-1)', '--s2:var(--space-2)', '--s3:var(--space-3)', '--s4:var(--space-4)', '--s5:20px', '--s6:var(--space-5)',
  '--s7:var(--space-6)', '--s8:var(--space-7)', '--r-sm:var(--radius-sm)', '--r-md:var(--radius-md)', '--r-lg:var(--radius-lg)',
  '--f-d:var(--font-display)', '--f-b:var(--font-text)',
];

const wrap = (decls) => decls.map((d) => '  ' + d + ';').join('\n');
const css = `/* Condisco Design System v${t.version} — generated by scripts/build-tokens.mjs from app/ds/tokens.json. Do not edit by hand.
   Source of truth: https://claude.ai/artifact/1Wq3HH1mTjxFr6yhLhtxEp */
:root{
  color-scheme:light dark;
${wrap(COLORS)}
${wrap(fam)}
${wrap(fs_)}
${wrap(list('spacing'))}
${wrap(list('radius'))}
${wrap(list('size'))}
${wrap(list('duration'))}
${wrap(list('easing'))}
${wrap(shadowLight)}
  /* legacy aliases (0.5.x only) */
${wrap(LEGACY)}
}
:root[data-theme=light]{color-scheme:light}
:root[data-theme=dark]{color-scheme:dark;
${wrap(shadowDark)}
}
@media (prefers-color-scheme:dark){:root:not([data-theme=light]){
${wrap(shadowDark)}
}}
/* breakpoints (CSS cannot read custom properties in media queries; keep these numbers in sync):
${(t.breakpoint?.tokens || []).map((b) => `   ${b.name} ${b.value}: ${b.usage}`).join('\n')} */
`;

// Kit block: the summaries share the same colours and fonts; the kit's own names map onto them.
const kitNames = ['bg', 'surface', 'surface-sunk', 'ink', 'ink-2', 'line', 'accent', 'win', 'win-ink',
  'box-idea', 'box-idea-line', 'box-core', 'box-core-line', 'box-ex', 'box-ex-line', 'box-trap', 'box-trap-line', 'box-add', 'box-add-line', 'ok', 'warn'];
const byName = Object.fromEntries(t.color.tokens.map((x) => [x.name, x]));
const KIT_ALIAS = { 'surface-sunk': 'sunk', 'ink-2': 'muted', win: 'mark', 'win-ink': 'mark-ink', 'box-idea': 'idea', 'box-idea-line': 'idea-line',
  'box-core': 'core', 'box-core-line': 'core-line', 'box-ex': 'ex', 'box-ex-line': 'ex-line', 'box-trap': 'trap', 'box-trap-line': 'trap-line', 'box-add': 'add', 'box-add-line': 'add-line' };
const kitBlock = '/* DS:TOKENS start — generated from app/ds/tokens.json by scripts/build-tokens.mjs; do not edit */\n'
  + kitNames.map((n) => `--${KIT_ALIAS[n] || n}:${colour(byName[n])};`).join('')
  + `--f-d:${t.type.families.display};--f-b:${t.type.families.text};`
  + '\n/* DS:TOKENS end */';

const kit = fs.readFileSync(KIT, 'utf8');
const re = /\/\* DS:TOKENS start[\s\S]*?\/\* DS:TOKENS end \*\//;
if (!re.test(kit)) { console.error('kit/template.html has no DS:TOKENS markers'); process.exit(1); }
const kitNew = kit.replace(re, kitBlock);

if (process.argv.includes('--check')) {
  const bad = [];
  if (!fs.existsSync(OUT) || fs.readFileSync(OUT, 'utf8') !== css) bad.push('app/ds/tokens.css is out of date');
  if (kit !== kitNew) bad.push('kit/template.html token block is out of date');
  if (bad.length) { console.error(bad.join('\n') + '\nrun: node scripts/build-tokens.mjs'); process.exit(1); }
  console.log('tokens up to date');
} else {
  fs.writeFileSync(OUT, css); fs.writeFileSync(KIT, kitNew);
  console.log('wrote app/ds/tokens.css and the kit token block');
}
